  into v_expected_count
  from catalog.custom_fields f
  where f.group_id = p_group_id;

  if array_length(p_ordered_field_ids, 1) <> v_expected_count then
    raise exception 'validation_exception: Ordered field ids must include all fields.';
  end if;

  for v_index in 1..array_length(p_ordered_field_ids, 1) loop
    v_field_id := p_ordered_field_ids[v_index];
    if not exists (
      select 1
      from catalog.custom_fields f
      where f.id = v_field_id
        and f.group_id = p_group_id
        and f.tenant_id = p_tenant_id
    ) then
      raise exception 'custom field not found';
    end if;

    update catalog.custom_fields f
    set sort_order = v_index - 1, updated_at = now()
    where f.id = v_field_id;
  end loop;
end;
$$;

create or replace function catalog.list_custom_field_config(
  p_tenant_id uuid
)
returns jsonb
language plpgsql
security definer
set search_path = catalog, iam, pg_temp
as $$
declare
  v_groups jsonb;
begin
  perform catalog._assert_custom_fields_permission(p_tenant_id);

  select coalesce(
    jsonb_agg(catalog._custom_field_group_to_json(g.id) order by g.sort_order, g.name),
    '[]'::jsonb
  )
  into v_groups
  from catalog.custom_field_groups g
  where g.tenant_id = p_tenant_id;

  return jsonb_build_object('groups', v_groups);
end;
$$;
